{
  "message": "Migrate UserView to Pydantic v2 validation and serialization APIs.",
  "rationale": "ConfigDict enables attribute input, field-name or alias population, and rejection of extra mapping fields while preserving integer coercion and required-field validation. model_validate and model_dump replace deprecated APIs, producing exactly id and displayName without changing the function signature or dependency pins.",
  "files": [
    {
      "path": "src/integration.py",
      "content": "from pydantic import BaseModel, ConfigDict, Field


class UserView(BaseModel):
    model_config = ConfigDict(
        from_attributes=True,
        populate_by_name=True,
        extra="forbid",
    )

    id: int
    display_name: str = Field(alias="displayName")


def serialize_user(value):
    return UserView.model_validate(value).model_dump(by_alias=True)
